mapper.select:
SELECT EXISTS (
  SELECT 1
  FROM watchlists
  WHERE watchlist_group_id = #{watchlistGroupId}
    AND instrument_id = #{instrumentId}
)

SELECT w.watchlist_id AS watchlistId, w.watchlist_group_id AS watchlistGroupId, wg.name AS watchlistName, w.instrument_id AS instrumentId, i.ticker AS symbol, i.name AS instrumentName, w.added_at AS addedAt, mqs.last_price AS lastPrice, mqs.change_pct AS changePct FROM watchlists w INNER JOIN instruments i ON i.instrument_id = w.instrument_id INNER JOIN watchlist_groups wg ON wg.watchlist_group_id = w.watchlist_group_id LEFT JOIN market_quote_snapshots mqs ON mqs.symbol = i.ticker WHERE w.account_id = #{accountId}
AND w.watchlist_group_id = #{watchlistGroupId}
ORDER BY w.added_at DESC

SELECT watchlist_group_id
FROM watchlist_groups
WHERE account_id = #{accountId}
  AND watchlist_group_id = #{watchlistGroupId}

SELECT account_id
FROM watchlists
WHERE account_id = #{accountId}
  AND watchlist_id = #{watchlistId}

mapper.delete:
DELETE FROM watchlists
WHERE account_id = #{accountId}
  AND watchlist_id = #{watchlistId}
